package com.xyh.cybersecurity.guard;

import com.fasterxml.jackson.databind.JsonNode;
import org.springframework.stereotype.Service;
import java.util.*;
import static com.xyh.cybersecurity.guard.GuardJson.*;

/** 候选登记、计划冻结、独立审查与报告封存；没有同 subject 验证材料就不能激活。 */
@Service
public class GuardCatalog {
    private final GuardStore store;private final GuardAccess access;private final GuardContracts contracts;
    private final GuardArtifacts artifacts;private final GuardModelRuntime runtime;private final GuardSignatures signatures;
    public GuardCatalog(GuardStore store,GuardAccess access,GuardContracts contracts,GuardArtifacts artifacts,GuardModelRuntime runtime,GuardSignatures signatures){this.store=store;this.access=access;this.contracts=contracts;this.artifacts=artifacts;this.runtime=runtime;this.signatures=signatures;}
    public JsonNode model(JsonNode b){access.permission("model.manage",null);fields(b,"manifestRef manifestSha256","");String ref=text(b,"manifestRef");JsonNode m=artifacts.json(ref,digest(b,"manifestSha256"));contracts.manifest(m);
        var key=map("contract_version",CONTRACT,"profile_sha256",contracts.profileHash(),"schema_set_sha256",contracts.schemaHash(),"extractor_sha256",text(m,"extractorSha256"));var c=store.one("guard_contract",key,false);
        if(c==null){key.put("status","frozen");c=store.add("guard_contract",key);}
        var row=store.insert("guard_model",map("public_id",uuid(m,"modelId"),"model_key",uuid(m,"modelId"),"version",text(m,"modelVersion"),"manifest_ref",ref,"manifest_sha256",text(b,"manifestSha256"),"artifact_sha256",text(m,"artifactSha256"),"contract_id",c.get("id"),"manifest_json",canonical(m),"created_by",access.human()));
        store.audit(access.human(),"guard.model.registered",str(row,"public_id"),null,null,b);return object("id",row.get("public_id"),"candidateOnly",true,"validationStatus","pending");}
    public JsonNode validation(String id,JsonNode b){access.permission("model.validate",null);fields(b,"validationProfileId","");require("host-guard-onnx-v1".equals(text(b,"validationProfileId")),"VALIDATION_PROFILE_UNSUPPORTED");var m=store.external("guard_model",id,true);
        JsonNode result;try{result=runtime.validate(m);}catch(com.xyh.cybersecurity.common.api.ApiRequestException e){result=object("status","failed","reasonCode",e.code());}
        store.update("guard_model",number(m,"id"),map("validation_status",result.path("status").asText(),"validation_json",canonical(result)));store.audit(access.human(),"guard.model.validated",id,null,null,result);return result;}
    public JsonNode dataset(JsonNode b){access.permission("dataset.manage",null);fields(b,"manifestRef manifestSha256","");JsonNode m=artifacts.json(text(b,"manifestRef"),digest(b,"manifestSha256"));text(m,"datasetKey");text(m,"version");
        var r=store.add("guard_dataset",map("dataset_key",text(m,"datasetKey"),"version",text(m,"version"),"manifest_ref",text(b,"manifestRef"),"manifest_sha256",text(b,"manifestSha256"),"payload_json",canonical(m)));return object("id",r.get("public_id"));}
    public JsonNode plan(JsonNode b){access.permission("evaluation.run",null);
        fields(b,"planKey version protocolVersions datasetRefs splitHashes behaviorSourceScope scenarioMappingSha256 labelTimelineSha256 captureHealthSha256 latencyRegistration metrics budget scenarioRefs","");versions(b.get("protocolVersions"));
        for(String k:List.of("scenarioMappingSha256","labelTimelineSha256","captureHealthSha256"))digest(b,k);
        require(b.path("datasetRefs").isArray()&&!b.get("datasetRefs").isEmpty()&&b.path("behaviorSourceScope").isArray()&&!b.get("behaviorSourceScope").isEmpty(),"EVALUATION_PLAN_MISMATCH");
        for(var d:b.get("datasetRefs"))store.external("guard_dataset",uuid(d.asText()),false);
        for(String k:List.of("splitHashes","latencyRegistration","metrics","budget"))require(b.path(k).isObject()&&!b.path(k).isEmpty(),"EVALUATION_PLAN_MISMATCH");
        require(b.path("splitHashes").has("train")&&b.path("splitHashes").has("selection")&&b.path("splitHashes").has("calibration")&&b.path("splitHashes").has("development"),"EVALUATION_PLAN_MISMATCH");
        for(String role:List.of("train","selection","calibration","development"))digest(b.get("splitHashes"),role);
        var r=store.add("guard_evaluation_plan",map("plan_key",text(b,"planKey"),"version",text(b,"version"),"plan_sha256",hash(b),"payload_json",canonical(b),"created_by",access.human()));return object("id",r.get("public_id"),"planSha256",hash(b));}
    public JsonNode capability(JsonNode b){access.permission("bundle.request",null);fields(b,"capabilityKey version platform adapterVersion addressFamily transport direction family profile behaviorScope latencyLimits level evidenceRef evidenceSha256 runnerIdentity","");
        require(Set.of("research","alert_only","lab_auto","authorized_auto").contains(text(b,"level")),"CAPABILITY_NOT_SUPPORTED");
        if(!"research".equals(text(b,"level"))){var report=signatures.report(artifacts.json(text(b,"evidenceRef"),digest(b,"evidenceSha256")),text(b,"runnerIdentity"));
            require(report.path("passed").asBoolean()&&report.path("capability").equals(withoutEvidence(b)),"CAPABILITY_NOT_SUPPORTED");versions(report.path("protocolVersions"));}
        var r=store.add("guard_capability",map("capability_key",text(b,"capabilityKey"),"version",text(b,"version"),"platform",text(b,"platform"),"level",text(b,"level"),"payload_json",canonical(b),"created_by",access.human()));return object("id",r.get("public_id"),"level",text(b,"level"));}
    private JsonNode withoutEvidence(JsonNode b){var n=b.deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)n).remove(List.of("evidenceRef","evidenceSha256","runnerIdentity"));return n;}
    public JsonNode policy(JsonNode b){access.permission("policy.draft",null);contracts.policy(b);var m=store.external("guard_model",uuid(b,"modelId"),false);var plan=store.one("guard_evaluation_plan",map("plan_sha256",text(b,"evaluationPlanSha256")),false);
        require(plan!=null&&json(m,"manifest_json").path("evaluationPlanSha256").asText().equals(text(b,"evaluationPlanSha256")),"EVALUATION_PLAN_MISMATCH");
        for(var cid:b.path("supportedCapabilityIds"))store.external("guard_capability",uuid(cid.asText()),false);
        var r=store.insert("guard_decision_policy",map("public_id",uuid(b,"policyId"),"policy_key",text(b,"policyId"),"version",text(b,"policyVersion"),"model_id",m.get("id"),"plan_id",plan.get("id"),"decision_contract_version",DECISION,"definition_json",canonical(b),"definition_sha256",hash(b),"created_by",access.human()));return object("id",r.get("public_id"),"status","draft","revision",1);}
    public JsonNode reviewPolicy(String id,JsonNode b,String revision){access.permission("policy.approve",null);GuardAdministration.decisionBody(b);var p=store.external("guard_decision_policy",id,true);access.revision(p,revision);access.different(p,"created_by");require("draft".equals(str(p,"status")),"STATE_CONFLICT");
        String status=text(b,"decision").equals("approve")?"reviewed":"retired";store.update("guard_decision_policy",number(p,"id"),map("status",status,"reviewed_by",access.human(),"revision",number(p,"revision")+1));store.audit(access.human(),"guard.policy."+status,id,null,null,b);return object("id",id,"status",status,"revision",number(p,"revision")+1);}
    public JsonNode bundle(JsonNode b){access.permission("bundle.request",null);fields(b,"modelId policyId featureProfileSha256 extractorSha256 protocolVersions evaluationPlanId capabilityIds environment","");versions(b.get("protocolVersions"));
        var m=store.external("guard_model",uuid(b,"modelId"),false);var p=store.external("guard_decision_policy",uuid(b,"policyId"),false);var plan=store.external("guard_evaluation_plan",uuid(b,"evaluationPlanId"),false);var c=store.get("guard_contract",number(m,"contract_id"));
        require(number(p,"model_id")==number(m,"id")&&number(p,"plan_id")==number(plan,"id")&&"reviewed".equals(str(p,"status"))&&"validated".equals(str(m,"validation_status")),"RELEASE_COMBINATION_INVALID");
        require(contracts.profileHash().equals(digest(b,"featureProfileSha256"))&&str(c,"extractor_sha256").equals(digest(b,"extractorSha256")),"PROFILE_HASH_MISMATCH");
        require(Set.of("research","lab","authorized").contains(text(b,"environment")),"INVALID_ENVIRONMENT");
        var ids=new TreeSet<String>();for(var i:b.path("capabilityIds"))require(ids.add(uuid(i.asText())),"CAPABILITY_NOT_SUPPORTED");var expected=new TreeSet<String>();for(var i:json(p,"definition_json").path("supportedCapabilityIds"))expected.add(i.asText());require(!ids.isEmpty()&&ids.equals(expected),"CAPABILITY_NOT_SUPPORTED");
        var subject=object("contractVersion",CONTRACT,"protocolVersions",versions(),"modelId",m.get("public_id"),"manifestSha256",m.get("manifest_sha256"),"policyId",p.get("public_id"),"policySha256",p.get("definition_sha256"),"featureProfileSha256",contracts.profileHash(),"extractorSha256",c.get("extractor_sha256"),"evaluationPlanSha256",plan.get("plan_sha256"),"capabilityIds",ids,"environment",text(b,"environment"));
        String id=id();var r=store.insert("guard_release_bundle",map("public_id",id,"bundle_key",id,"version","1","model_id",m.get("id"),"policy_id",p.get("id"),"contract_id",c.get("id"),"plan_id",plan.get("id"),"environment",text(b,"environment"),"subject_json",canonical(subject),"subject_sha256",hash(subject),"requested_by",access.human()));
        for(String cid:ids){var cap=store.external("guard_capability",cid,false);store.add("guard_bundle_capability",map("bundle_id",r.get("id"),"capability_id",cap.get("id")));}
        store.audit(access.human(),"guard.bundle.requested",id,null,null,subject);return object("id",id,"subjectSha256",hash(subject),"status","candidate","revision",1);}
    public JsonNode report(String bundleId,JsonNode b){access.permission("evaluation.run",null);fields(b,"reportRef sha256 runnerIdentity","");var bundle=store.external("guard_release_bundle",bundleId,true);require("candidate".equals(str(bundle,"status")),"STATE_CONFLICT");
        var report=signatures.report(artifacts.json(text(b,"reportRef"),digest(b,"sha256")),text(b,"runnerIdentity"));versions(report.path("protocolVersions"));var plan=store.get("guard_evaluation_plan",number(bundle,"plan_id"));
        require(str(bundle,"subject_sha256").equals(report.path("subjectSha256").asText())&&str(plan,"plan_sha256").equals(report.path("evaluationPlanSha256").asText()),"EVALUATION_PLAN_MISMATCH");
        require(Set.of("development","final","replay","canary","platform").contains(text(report,"runKind")),"EVALUATION_PLAN_MISMATCH");
        var r=store.add("guard_evaluation_run",map("plan_id",plan.get("id"),"bundle_id",bundle.get("id"),"run_kind",text(report,"runKind"),"runner_identity",text(b,"runnerIdentity"),"status",report.path("passed").asBoolean()?"passed":"failed","report_ref",text(b,"reportRef"),"report_sha256",text(b,"sha256"),"payload_json",canonical(report)));return object("id",r.get("public_id"),"status",r.get("status"));}
    public JsonNode seal(String id,JsonNode b,String revision){access.permission("bundle.request",null);fields(b,"evaluationIds","");var bundle=store.external("guard_release_bundle",id,true);access.revision(bundle,revision);require("candidate".equals(str(bundle,"status")),"STATE_CONFLICT");require(b.path("evaluationIds").isArray()&&!b.get("evaluationIds").isEmpty(),"EVALUATION_PLAN_MISMATCH");
        var reports=new ArrayList<JsonNode>();var kinds=new HashSet<String>();
        for(var rid:b.get("evaluationIds")){var r=store.external("guard_evaluation_run",uuid(rid.asText()),false);require(number(r,"bundle_id")==number(bundle,"id")&&"passed".equals(str(r,"status")),"EVALUATION_PLAN_MISMATCH");kinds.add(str(r,"run_kind"));reports.add(object("evaluationId",r.get("public_id"),"reportSha256",r.get("report_sha256")));}
        require(kinds.contains("final"),"FINAL_EVALUATION_REQUIRED");
        if(!"research".equals(str(bundle,"environment")))require(kinds.containsAll(Set.of("platform","canary")),"JOINT_EVALUATION_REQUIRED");
        reports.sort(Comparator.comparing(x->x.path("evaluationId").asText()));JsonNode sealed=object("subjectSha256",bundle.get("subject_sha256"),"reports",reports);
        store.update("guard_release_bundle",number(bundle,"id"),map("sealed_manifest_json",canonical(sealed),"sealed_manifest_sha256",hash(sealed),"status","evaluated","revision",number(bundle,"revision")+1));store.audit(access.human(),"guard.bundle.sealed",id,null,null,sealed);return object("id",id,"status","evaluated","revision",number(bundle,"revision")+1,"sealedManifestSha256",hash(sealed));}
    public JsonNode approveBundle(String id,JsonNode b,String revision){access.permission("bundle.approve",null);GuardAdministration.decisionBody(b);var bundle=store.external("guard_release_bundle",id,true);access.revision(bundle,revision);access.different(bundle,"requested_by");require("evaluated".equals(str(bundle,"status"))&&bundle.get("sealed_manifest_sha256")!=null,"STATE_CONFLICT");
        String status=text(b,"decision").equals("approve")?"approved":"retired";store.update("guard_release_bundle",number(bundle,"id"),map("status",status,"approved_by",access.human(),"revision",number(bundle,"revision")+1));store.audit(access.human(),"guard.bundle."+status,id,null,null,b);return object("id",id,"status",status,"revision",number(bundle,"revision")+1);}
    public JsonNode activate(String id,JsonNode b,String revision){fields(b,"assetIds authorizationIds","");require(b.path("assetIds").isArray()&&!b.get("assetIds").isEmpty()&&b.get("assetIds").size()<=32&&b.path("authorizationIds").isArray()&&b.get("assetIds").size()==b.get("authorizationIds").size(),"INVALID_REQUEST");
        var bundle=store.external("guard_release_bundle",id,false);access.permission("bundle.approve",null);access.revision(bundle,revision);require(Set.of("approved","active").contains(str(bundle,"status")),"STATE_CONFLICT");
        var pairs=new TreeMap<Long,String>();for(int i=0;i<b.get("assetIds").size();i++){var a=store.external("asset",uuid(b.get("assetIds").get(i).asText()),false);require(pairs.put(number(a,"id"),uuid(b.get("authorizationIds").get(i).asText()))==null,"INVALID_REQUEST");}
        var ids=new ArrayList<String>();for(var pair:pairs.entrySet()){long aid=pair.getKey();access.permission("bundle.approve",aid);var a=store.lockAsset(aid);var auth=store.external("asset_authorization",pair.getValue(),true);var now=store.now();
            require(number(auth,"asset_id")==aid&&"active".equals(str(auth,"status"))&&!now.isBefore(instant(auth.get("valid_from")))&&now.isBefore(instant(auth.get("valid_until")))&&str(bundle,"environment").equals(str(a,"environment")),"AUTHORIZATION_INACTIVE");
            var policy=store.get("guard_decision_policy",number(bundle,"policy_id"));require("reviewed".equals(str(policy,"status")),"STATE_CONFLICT");
            for(var c:store.rows("guard_bundle_capability",map("bundle_id",bundle.get("id")),false,100)){var cap=store.get("guard_capability",number(c,"capability_id"));String env=str(a,"environment");String mode=json(policy,"definition_json").path("mode").asText();
                if(!"alert_only".equals(mode))require(("lab".equals(env)&&Set.of("lab_auto","authorized_auto").contains(str(cap,"level")))||("authorized".equals(env)&&"authorized_auto".equals(str(cap,"level"))),"CAPABILITY_NOT_SUPPORTED");}
            for(var old:store.rows("guard_asset_binding",map("asset_id",aid,"status","active"),true,100))store.update("guard_asset_binding",number(old,"id"),map("status","suspended","revision",number(old,"revision")+1));
            var row=store.add("guard_asset_binding",map("asset_id",aid,"bundle_id",bundle.get("id"),"authorization_id",auth.get("id"),"authorization_revision",auth.get("revision"),"status","active","activated_by",access.human()));ids.add(str(row,"public_id"));store.audit(access.human(),"guard.bundle.activated",id,aid,null,b);
        }
        bundle=store.external("guard_release_bundle",id,true);access.revision(bundle,revision);store.update("guard_release_bundle",number(bundle,"id"),map("status","active","revision",number(bundle,"revision")+1));return object("id",id,"bindingIds",ids,"status","active","revision",number(bundle,"revision")+1);}
}
